const BAMBOO_INFO={id:"bamboo-craft",title:"Bamboo Craft of India",originRegions:"North-East India, Assam, Meghalaya, Mizoram, Tripura, and other bamboo-rich regions",history:"traditional bamboo craft has long sustained rural livelihoods across India, especially in the North-East, where bamboo is one of the most versatile natural resources.",materials:"Bamboo, rattan, natural resins, cane, mud, and plant-based dyes",quickStats:[{label:"Regions",value:"North-East + India",icon:"📍"},{label:"Material",value:"Bamboo & Cane",icon:"🎋"},{label:"Uses",value:"Furniture, Baskets, Lamps",icon:"🪵"},{label:"Sustainability",value:"Fast-Growing & Renewable",icon:"🌿"},{label:"Craft Legacy",value:"Centuries Old",icon:"🏺"},{label:"Identity",value:"Eco-Friendly Living Art",icon:"✨"}]},REGIONAL_CRAFTS=[{name:"Assam",description:"Assam is renowned for bamboo cane weaving, tea garden baskets, utility containers, and bamboo lamps shaped by local artisans.",highlight:"Bamboo & cane weaving"},{name:"Meghalaya",description:"The Khasi and Garo traditions are famous for bamboo furniture, storage baskets, and eco-friendly domestic objects made in village workshops.",highlight:"Rural craft clusters"},{name:"Mizoram",description:"Mizoram combines bamboo craft with social and ritual life through woven mats, stools, decorative partitions, and bamboo-based architecture.",highlight:"Household and ceremonial craft"},{name:"Tripura",description:"Tripura has a rich bamboo basketry tradition connected to storage, food preparation, and culturally coded woven forms used in daily life.",highlight:"Basketry heritage"}],PROCESS_STEPS=[{step:1,title:"Harvesting & Selection",description:"Artisans source mature bamboo from nearby forests or village groves, selecting species suited for flexibility, strength, and durability.",image:"assets/bamboo-technique-1.svg"},{step:2,title:"Cutting & Splitting",description:"Bamboo poles are cut and split into narrow slats or strands depending on whether the final object is woven, carved, or bent.",image:"assets/bamboo-technique-1.svg"},{step:3,title:"Soaking & Treatment",description:"The material is soaked or smoked to improve flexibility and resist insect attack while maintaining natural grain and strength.",image:"assets/bamboo-technique-2.svg"},{step:4,title:"Weaving & Shaping",description:"Skilled artisans weave patterns, braid strips, or bend sections into containers, furniture, and decorative objects using age-old methods.",image:"assets/bamboo-weaving.svg"},{step:5,title:"Finishing & Preservation",description:"The craft is polished, oiled, or treated with natural finishes to extend life while preserving the warm organic character of bamboo.",image:"assets/bamboo-technique-2.svg"}],GALLERY_ITEMS=[{title:"Woven Bamboo Basket",caption:"Traditional multipurpose basket used for storage, harvesting, and gifting.",image:"assets/bamboo-product.svg"},{title:"Bamboo Lamp",caption:"Handcrafted bamboo lanterns and lamps that blend rural craft with graceful modern aesthetics.",image:"assets/bamboo-weaving.svg"},{title:"Bamboo Stool & Furniture",caption:"Strong and lightweight bamboo furniture made for local interiors and sustainable living.",image:"assets/bamboo-harvest.svg"}],SUSTAINABILITY_POINTS=[{title:"Rapid Renewable Resource",description:"Bamboo grows quickly and can be harvested without long forest cycles, making it a renewable material for daily use."},{title:"Low-Carbon Production",description:"Most bamboo products are handcrafted with minimal energy, reducing reliance on industrial processing and fossil fuel consumption."},{title:"Circular Local Livelihoods",description:"Bamboo craft keeps value in rural communities by supporting artisan incomes, forest-linked employment, and local markets."}],REFERENCES=[{text:"Ministry of Textiles, Government of India — Handicrafts and Bamboo Craft initiatives.",link:"https://handicrafts.nic.in"},{text:"North-East India bamboo and cane craft documentation and village enterprise studies.",link:"#"},{text:"UNDP / local livelihood reports on bamboo-based sustainable crafts in the North-East.",link:"#"}];"undefined"!=typeof module&&module.exports&&(module.exports={BAMBOO_INFO:BAMBOO_INFO,REGIONAL_CRAFTS:REGIONAL_CRAFTS,PROCESS_STEPS:PROCESS_STEPS,GALLERY_ITEMS:GALLERY_ITEMS,SUSTAINABILITY_POINTS:SUSTAINABILITY_POINTS,REFERENCES:REFERENCES});